package credentialhelper

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"gitlab.com/gitlab-org/cli/internal/api"
	"gitlab.com/gitlab-org/cli/internal/cmdutils"
	"gitlab.com/gitlab-org/cli/internal/glrepo"
	"gitlab.com/gitlab-org/cli/internal/mcpannotations"
)

type responseType any

type errorResponseType struct{}

func (errorResponseType) MarshalJSON() ([]byte, error) {
	return []byte(`"error"`), nil
}

type successResponseType struct{}

func (successResponseType) MarshalJSON() ([]byte, error) {
	return []byte(`"success"`), nil
}

type response struct {
	Type        successResponseType `json:"type"` // always evaluates to "success"
	InstanceURL string              `json:"instance_url"`
	Token       token               `json:"token"`
}

type token struct {
	Type            string    `json:"type"`
	Token           string    `json:"token"`
	ExpiryTimestamp time.Time `json:"expiry_timestamp,omitzero"`
}

type errorResponse struct {
	Type    errorResponseType `json:"type"` // always evaluates to "error"
	Message string            `json:"message"`
}

type options struct {
	baseRepo  func() (glrepo.Interface, error)
	apiClient func(repoHost string) (*api.Client, error)
}

func NewCmd(f cmdutils.Factory) *cobra.Command {
	opts := &options{
		baseRepo:  f.BaseRepo,
		apiClient: f.ApiClient,
	}

	writeResponse := func(resp responseType) error {
		io := f.IO()
		enc := json.NewEncoder(io.StdOut) //nolint:forbidigo // git credential helper protocol writes JSON to both stdout and stderr; PrintJSON only handles stdout
		if err := enc.Encode(resp); err != nil {
			errEnc := json.NewEncoder(io.StdErr) //nolint:forbidigo // git credential helper protocol error response on stderr
			if err := errEnc.Encode(errorResponse{Message: err.Error()}); err != nil {
				return err
			}
			return cmdutils.SilentError
		}
		return nil
	}

	cmd := &cobra.Command{
		Use:    "credential-helper [flags]",
		Args:   cobra.NoArgs,
		Short:  "Implements a generic credential helper.",
		Hidden: true,
		Annotations: map[string]string{
			mcpannotations.Exclude: "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			resp := opts.run(cmd.Context())

			return writeResponse(resp)
		},
	}

	cmdutils.EnableRepoOverride(cmd, f)
	// NOTE: this is a hack to ensure the JSON protocol for the hook that EnableRepoOverride added.
	repoOverridePersistentPreRunE := cmd.PersistentPreRunE
	cmd.PersistentPreRunE = func(cmd *cobra.Command, args []string) error {
		err := repoOverridePersistentPreRunE(cmd, args)
		if err != nil {
			_ = writeResponse(errorResponse{Message: err.Error()})
			// We need to signal cobra that we want to error, but that cobra shouldn't log anything else.
			// This silent error is the way to go here.
			return cmdutils.SilentError
		}
		return nil
	}

	return cmd
}

func (o *options) run(ctx context.Context) responseType {
	baseRepo, err := o.baseRepo()
	host := "" // NOTE: an empty host is the default configured host
	if err == nil {
		host = baseRepo.RepoHost()
	}

	apiClient, err := o.apiClient(host)
	if err != nil {
		return errorResponse{Message: err.Error()}
	}

	// NOTE: the API client ensures this suffix via glinstance.APIEndpoint().
	instanceURL := strings.TrimSuffix(apiClient.BaseURL(), "/api/v4/")

	cred, err := apiClient.Credential(ctx)
	switch {
	case errors.Is(err, api.ErrUnauthenticated):
		return errorResponse{Message: "glab is not authenticated. Use glab auth login to authenticate"}
	case errors.Is(err, api.ErrUnsupportedAuthSource):
		return errorResponse{Message: "unable to determine token"}
	case err != nil:
		return errorResponse{Message: fmt.Sprintf("failed to read the credentials for %q: %v", host, err)}
	}

	return response{
		InstanceURL: instanceURL,
		Token: token{
			Type:            string(cred.Kind),
			Token:           cred.Token,
			ExpiryTimestamp: cred.Expiry.UTC(),
		},
	}
}

package docker

import (
	"errors"
	"fmt"

	"gitlab.com/gitlab-org/cli/internal/config"
	"gitlab.com/gitlab-org/cli/internal/dockercredhelper"
	"gitlab.com/gitlab-org/cli/internal/iostreams"
)

func configureDocker(iostreams *iostreams.IOStreams, cfg config.Config) error {
	installation, err := dockercredhelper.Install()
	if err != nil {
		return err
	}
	if !installation.OnPath {
		iostreams.LogErrorf("%s %s\n", iostreams.Color().WarnIcon(), installation.PathWarning())
	}

	hostnames, err := cfg.Hosts()
	if err != nil {
		return fmt.Errorf("fetching list of hosts handled by glab: %w", err)
	}

	var configuredDomains []string
	var readErr error
	for _, hostname := range hostnames {
		// Report a read failure and carry on so the remaining hosts are still
		// configured, but keep it to decide the exit below: "no domains are
		// configured" and "your domains could not be read" need different
		// messages, and a partial failure must not be reported as full success.
		domains, err := readDomains(cfg, hostname, "container_registry_domains")
		if err != nil {
			readErr = errors.Join(readErr, err)
			iostreams.LogErrorf("%s Skipped %s: %v\n", iostreams.Color().WarnIcon(), hostname, err)
			continue
		}
		configuredDomains = append(configuredDomains, domains...)
	}

	if len(configuredDomains) == 0 {
		// Telling the user to go configure a domain would misdirect when the
		// domains they already have are the thing that could not be read.
		if readErr != nil {
			return readErr
		}
		return fmt.Errorf(
			"no hosts were configured - " +
				"ensure you've logged in via oauth2 and configured " +
				"at least one container registry domain for a host")
	}

	dir, err := dockercredhelper.ConfigDir()
	if err != nil {
		return err
	}

	registrations, err := dockercredhelper.Register(dir, configuredDomains...)
	if err != nil {
		return err
	}

	for _, registration := range registrations {
		iostreams.LogInfof("%s Configured Docker credential helper for %s\n", iostreams.Color().GreenCheck(), registration.Domain)
		if registration.ShadowedLogin {
			iostreams.LogErrorf("%s %s\n", iostreams.Color().WarnIcon(), registration.ShadowedLoginWarning())
		}
	}

	// readErr still fails the command even though every readable host was
	// configured above: a CI script gating on `configure-docker` (for
	// example, `glab auth configure-docker && docker pull ...`) needs a
	// non-zero exit to detect that a host's registries were left
	// unauthenticated, rather than only finding out later from an
	// unrelated-looking `docker pull` failure.
	return readErr
}

