package agentutils

import (
	"fmt"
	"strings"

	"github.com/spf13/pflag"

	"gitlab.com/gitlab-org/cli/internal/cmdutils"
)

const (
	KeyringFilesystemFallback CacheMode = "keyring-filesystem-fallback"
	ForcedKeyringCacheMode    CacheMode = "force-keyring"
	ForcedFilesystemCacheMode CacheMode = "force-filesystem"
	NoCacheCacheMode          CacheMode = "no"
)

var CacheModes = []CacheMode{KeyringFilesystemFallback, ForcedKeyringCacheMode, ForcedFilesystemCacheMode, NoCacheCacheMode}

type CacheMode = string

func AddTokenCacheModeFlag(fl *pflag.FlagSet, f *string) {
	fl.VarP(cmdutils.NewEnumValue(CacheModes, ForcedKeyringCacheMode, f), "cache-mode", "c", fmt.Sprintf("Mode to use for caching the token. Allowed values: %s.", strings.Join(CacheModes, ", ")))
}

package agentutils

import (
	"encoding/base64"
	"fmt"
	"strings"

	gitlab "gitlab.com/gitlab-org/api/client-go/v3"
)

// CachedToken represents a cached agent token
type CachedToken struct {
	ID        string
	AgentID   int64
	GitLabURL string
	Token     *gitlab.PersonalAccessToken
	Source    string
	FilePath  string // For filesystem tokens (optional)
	Expired   bool   // For list command
	Revoked   bool   // For list command
}

// ParseCacheID parses a cache ID in the format base64(gitlab-url)-agentID
func ParseCacheID(cacheID string) (string, int64, error) {
	// Cache ID format: base64(gitlab-url)-agentID
	// Split on the last hyphen to separate base64 URL from agent ID
	encodedURL, agentIDStr, found := strings.Cut(cacheID, "-")
	if !found {
		return "", 0, fmt.Errorf("invalid cache ID format")
	}

	// Parse the agent ID
	var agentID int64
	if _, err := fmt.Sscanf(agentIDStr, "%d", &agentID); err != nil {
		return "", 0, fmt.Errorf("invalid agent ID in cache ID: %w", err)
	}

	// Decode the base64-encoded GitLab URL
	urlBytes, err := base64.StdEncoding.DecodeString(encodedURL)
	if err != nil {
		return "", 0, fmt.Errorf("failed to decode GitLab URL: %w", err)
	}

	return string(urlBytes), agentID, nil
}

// FilterByAgents filters a slice of cached tokens by agent IDs
func FilterByAgents(tokens []CachedToken, agents []int64) []CachedToken {
	if len(agents) == 0 {
		return tokens
	}

	// Use struct{} to minimize per-entry allocation
	agentSet := make(map[int64]struct{}, len(agents))
	for _, agentID := range agents {
		agentSet[agentID] = struct{}{}
	}

	// Preallocate at most len(tokens); keeps append amortized O(1)
	filtered := make([]CachedToken, 0, len(tokens))
	for _, token := range tokens {
		if _, ok := agentSet[token.AgentID]; ok {
			filtered = append(filtered, token)
		}
	}

	return filtered
}

package agentutils

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	gitlab "gitlab.com/gitlab-org/api/client-go/v3"
)

func TestParseCacheID_Valid(t *testing.T) {
	// base64("https://gitlab.com") = aHR0cHM6Ly9naXRsYWIuY29t
	cacheID := "aHR0cHM6Ly9naXRsYWIuY29t-123"

	url, agentID, err := ParseCacheID(cacheID)
	require.NoError(t, err)
	assert.Equal(t, "https://gitlab.com", url)
	assert.Equal(t, int64(123), agentID)
}

func TestParseCacheID_Invalid_Format(t *testing.T) {
	_, _, err := ParseCacheID("invalid")
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid cache ID format")
}

func TestParseCacheID_Invalid_AgentID(t *testing.T) {
	// still a valid base64 but agent part is not numeric
	cacheID := "aHR0cHM6Ly9naXRsYWIuY29t-abc"
	_, _, err := ParseCacheID(cacheID)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid agent ID")
}

func TestFilterByAgents_Subset(t *testing.T) {
	tokens := []CachedToken{
		{AgentID: 1, Token: &gitlab.PersonalAccessToken{}},
		{AgentID: 2, Token: &gitlab.PersonalAccessToken{}},
		{AgentID: 3, Token: &gitlab.PersonalAccessToken{}},
		{AgentID: 4, Token: &gitlab.PersonalAccessToken{}},
	}

	filtered := FilterByAgents(tokens, []int64{1, 3})
	require.Len(t, filtered, 2)
	assert.Equal(t, int64(1), filtered[0].AgentID)
	assert.Equal(t, int64(3), filtered[1].AgentID)
}

func TestFilterByAgents_NoFilter(t *testing.T) {
	tokens := []CachedToken{
		{AgentID: 1, Token: &gitlab.PersonalAccessToken{}},
		{AgentID: 2, Token: &gitlab.PersonalAccessToken{}},
